// Imports
import ChangeOwner from "@/components/SettingsDialogs/ChangeOwner.vue";
import SnackBar from "@/components/SnackBar.vue";
import AdminAccess from "@/components/SettingsDialogs/AdminAccess.vue";
import RemoveAdmin from "@/components/SettingsDialogs/RemoveAdmin.vue";
import { list_users } from "@/graphql/queries.js";
import { get_all_users } from "@/mixins/GetAllUsers.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  // Components
  components: {
    AdminAccess,
    RemoveAdmin,
    SnackBar,
    ChangeOwner
  },
  // Mixins
  mixins: [get_all_users],
  // Props
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  // Data
  data() {
    return {
      // Component data
      SnackBarComponent: {},
      windowHeight: 0,
      // Table properties
      tableData: [],
      tableLoading: false,
      // Table headers
      headers: [{
        title: "User Name",
        key: "full_user_name",
        sortable: false
      }, {
        title: "User Email",
        key: "user_email_id",
        sortable: false
      }, {
        title: "Role",
        key: "user_type",
        sortable: false
      }, {
        title: "Action",
        key: "action",
        sortable: false
      }],
      // Dialog states
      componentCheck: 0,
      adminAccess: false,
      deleteAdmin: false,
      ownerupdate: false,
      // User data
      userArray: [],
      rowInfo: {},
      // Search and pagination
      search: "",
      currentPage: 1,
      itemsPerPage: 10
    };
  },
  // Lifecycle hooks
  mounted() {
    this.windowHeight = window.innerHeight - 260;
  },
  async created() {
    await this.get_admins();
    await this.get_all_users();
  },
  // Watchers
  watch: {
    searchValue: {
      handler(newVal) {
        this.search = newVal;
        this.currentPage = 1;
      },
      immediate: true
    },
    search() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      // When the page changes, scroll to top of table (optional)
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    },
    // Reset current page if it's out of bounds
    pageCount(newVal) {
      if (this.currentPage > newVal && newVal > 0) {
        this.currentPage = newVal;
      }
    }
  },
  // Computed properties
  computed: {
    filteredItems() {
      if (!this.search || this.search.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.search.toLowerCase().trim();
      return this.tableData.filter(item => item.full_user_name.toLowerCase().includes(searchTerm) || item.user_email_id.toLowerCase().includes(searchTerm) || item.user_type.toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // Sort the filtered items
      return this.filteredItems.slice().sort((a, b) => {
        // Default sort by user name
        const aValue = a.full_user_name ? a.full_user_name.toLowerCase() : "";
        const bValue = b.full_user_name ? b.full_user_name.toLowerCase() : "";
        return aValue.localeCompare(bValue);
      });
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Methods
  methods: {
    // Dialog management methods
    change_admin(item) {
      this.componentCheck = 3;
      this.rowInfo = item;
      this.ownerupdate = true;
    },
    async add_action() {
      this.userArray = [];
      await this.get_all_users();
      this.listUsers.forEach(element => {
        if (!this.tableData.some(data => data.user_id === element.user_id)) {
          this.userArray.push({
            username: element.full_user_name,
            userId: element.user_id
          });
        }
      });
      this.userArray.sort((a, b) => a.username.localeCompare(b.username));
      this.componentCheck = 1;
      this.adminAccess = true;
    },
    delete_admin(item) {
      this.componentCheck = 2;
      this.deleteAdmin = true;
      this.rowInfo = item;
    },
    close_dialogs(val) {
      if (val == 0) {
        this.adminAccess = false;
        this.deleteAdmin = false;
      }
    },
    // Data fetching methods
    async get_admins() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_users, {
          organization_id: data.organization.organization_id,
          user_status: "ACTIVE",
          user_type: "ADMIN",
          limit: 1000,
          next_token: null
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = result.data.list_users;
        response.details.forEach(element => {
          if (element.user_type != "CHATBOT") {
            this.tableData.push({
              full_user_name: element.full_user_name,
              user_email_id: element.user_email_id,
              user_id: element.user_id,
              user_type: element.user_type
            });
          }
        });
        this.$store.commit("SetadministrationCheck", true);
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Navigation methods
    back_action() {
      this.$emit("backAction", 0);
    },
    goToPage(page) {
      if (page >= 1 && page <= this.pageCount) {
        this.currentPage = page;
      }
    },
    // Search and sorting methods
    handleSearchChange(value) {
      this.search = value;
      this.currentPage = 1;
    },
    handleSortChange(value) {
      // Implement sorting logic here
    },
    // Styling methods
    getRoleColor(role) {
      switch (role) {
        case "OWNER":
          return "deep-purple lighten-4";
        case "ADMIN":
          return "blue lighten-4";
        case "SUPER_ADMIN":
          return "indigo lighten-4";
        default:
          return "grey lighten-4";
      }
    },
    getRoleTextColor(role) {
      switch (role) {
        case "OWNER":
          return "deep-purple darken-2";
        case "ADMIN":
          return "blue darken-2";
        case "SUPER_ADMIN":
          return "indigo darken-2";
        default:
          return "grey darken-2";
      }
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.ownerupdate = false;
      this.adminAccess = false;
      this.deleteAdmin = false;
      this.get_admins();
      this.get_all_users();
    }
  }
};
